-- Tips from the content review (2026-10-04): new tips for missing explanations (por vs para, se lo, hace … que, debe estar,
-- iba a venir…), and tips changed to lead with the porteño form. Bodies that had later corrections were merged by hand.

insert into public.tips (id, unit_id, title_en, body_md, status) values ('89ceed83-6de5-5102-bf3b-75fb12b34e48', '0323848f-596e-579a-a7dd-1904e93c1f32', 'Dijo que iba a venir', 'Reporting a promise: «voy» → **dijo que iba a venir**; «te llamo» → **dijo que me iba a llamar**. That is what porteños say day to day. In writing and in careful speech the same thing goes into *would*: **dijo que vendría**, **dijo que me llamaría** — learn to recognise it.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('53370f9c-ba05-5f62-b511-24a2a447f934', '13fec277-30b8-5bdb-9718-e682351abfd9', 'Un pantalón, un jean', 'One pair of pants is **un pantalón** — singular: *este pantalón es lindo*. *Los pantalones* works too. The same goes for **un jean**. And three colours: **celeste** is the light blue of the flag; **rosa** and **naranja** never change: *una remera rosa*, *un pantalón naranja*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('9739d026-23b1-5b91-ab4b-366dd163aadb', '13fec277-30b8-5bdb-9718-e682351abfd9', 'Es lindo, está lindo', 'With **ser** an adjective says what something is like; with **estar**, how it is right now. *Esa remera **es** linda* — it is a nice T-shirt. *¡**Estás** linda!* — you look nice today. *El café de acá **es** rico* — *este café **está** rico*. And **ser listo** is *to be clever*, while **estar listo** is *to be ready*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('c3471351-e02c-588e-853f-cff708c42c38', '20eecfc9-6b84-54ae-aedc-1c389863baf9', 'Telling it', 'A scare story has its set pieces: **de repente** — *suddenly*; **me pegué un susto** — *I got such a fright*; **salí corriendo** — *I ran off* (more natural than a bare *corrí*); **casi me muero**; **pensé que era un ladrón**; and the relief: **al final no era nada**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('a2499f0a-6b22-5381-ac0b-dd40ce7d8572', '28506229-594f-503e-80d4-5a3a1085320a', 'Aclarar', 'To clear it up — **aclarar**: **quiero aclarar algo**. Then: **no quise decir eso** — *I didn''t mean that*; **me expresé mal** — *I put it badly*; **me entendiste mal** — *you misunderstood me*; **no lo dije por vos** — *I didn''t say it about you*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('bd066d7e-c2a1-50d3-8b02-143dea692406', '2fa4826d-6276-5a6f-b7a5-e3c2e6dc4f2d', 'Hace = ago', '**Hace** + a time is *ago*: **llegué hace una hora** — *I got here an hour ago*; **hablé con Juan hace dos días**. *Not long ago* is **hace poco**, and the question is **¿hace cuánto?** — *how long ago?*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('7bc7d559-171b-5d91-a113-cdfdadc81e93', '2fd57a10-eb7b-5c55-9f86-fd2716e2ed87', 'Me olvidé or se me pasó?', 'A thing left behind is **me olvidé**: **me olvidé las llaves**. Something you did not remember to do is **se me pasó**: **se me pasó llamar a mi vieja** — or **me olvidé de llamar**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('dc9f86b5-115a-57f2-aeb5-e87bda316574', '3376ea65-8afe-56be-bae8-b5d06b46c9cd', 'The short ones', 'A few commands you will hear all day: *go* is **andá**; *hacer* gives **hacé**; *dar* gives **dame** — *give me*. The same recipe makes the rest: **poné** (put), **tené** (have, hold), **decí** (say), **salí** (go out). Never *ve, haz, pon, di* — those belong to another Spanish.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('295c40a8-2ee4-5735-8f87-9204d04bc6a2', '36b953db-b59d-5c37-8572-47afd0081c48', '¿Hay novedades?', 'News about people is **novedades**: **¿hay novedades de Juan?**, **todavía no hay novedades**. *Noticias* is what is on TV. Good news gets **¡buenísimo!**; bad news **¡qué mal!** or **lo siento mucho**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('4c27d57f-0d22-59ff-8b56-32eec37c86f1', '3cc8b1a1-6314-5a4f-be82-b713ea584203', 'Nosotras, ellas', '**Nosotras** and **ellas** are for groups of women only. One man in the group makes it **nosotros** and **ellos**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('eabe4bb4-b4b7-57af-b972-d1468b00c490', '3cc8b1a1-6314-5a4f-be82-b713ea584203', 'Nuestro, nuestra', '*Our* matches the thing, not the people: **nuestro** país, **nuestra** familia, **nuestros** hijos, **nuestras** hermanas. *Their* is still **su**: *su familia*, *sus hijos*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('7b5302fb-5521-5119-bbb6-dfeb663b58e8', '3dd370c2-01fe-54ba-95fc-3c5ef1637eb0', 'Debe estar', 'To state a guess, porteños mostly say **debe** + infinitive: **debe estar en el laburo** — *he must be at work*; **debe tener cuarenta**; **deben ser las ocho**. The future is more for the question: **¿dónde estará?**, **¿qué hora será?**', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('5f340b2a-1618-5fa1-b109-d96d8e4bb037', '41b8c894-067c-540c-88b8-1a334f63f9e2', 'Not for ordering', '*Me gustaría* is for wishes and plans. To order or to offer, porteños use **quería** and **¿querés?**: **quería dos entradas**, **¿querés unas medialunas?**, **¿querés tomar unos mates?**', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('d848ca5a-83f6-5ef0-82e0-4395a0511149', '43405ea2-1cec-5d90-bb61-d884ee8359bb', 'Te voy a esperar', 'With two verbs, the little word goes before the first one or on the end of the second — never in between: **te voy a esperar** = **voy a esperarte**; **¿me vas a ayudar?** = **¿vas a ayudarme?** Porteños mostly put it first.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('adee085f-4ac3-518d-8f86-26f3fee2843a', '51c29d65-4514-5131-bc0a-f7a48158b1db', 'Me tocó: I got', '**Me tocó** is also what you *got* without choosing: **me tocó el baño** — *I got the bathroom*; **me tocó laburar el domingo** — *I had to work on Sunday*; **me tocó un profe re copado** — *I got a really cool teacher*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('1d43e9b9-80e9-5f3c-b2cb-a7c32890b5fc', '52f4c57b-461b-5689-bc83-625e8445b0b2', '¡Hubieras avisado!', 'On its own, **hubieras** + participle is a reproach — *you should have*: **¡hubieras avisado!** — *you should have told me!* As a question it is *would you have…?*: **¿hubieras ido?** And for *we shouldn''t have*, add **no**: **no tendríamos que haber venido**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('c390a55a-7850-5978-8cf2-5e9ab1cb7fa0', '577ff67b-76f7-513b-adca-5871bbb950dc', 'Transfiero, transferís', '*Transferir* changes e to ie when the stress falls on it: yo **transfiero**, él **transfiere**. With vos the stress moves, so it stays: **transferís**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('4be9d9ea-b2f7-5b90-8382-a6108a0ffd65', '59c95af3-6785-5037-9294-f36861623e46', 'Out loud: ¿se puede?', '**Se permite** and **se prohíbe** are sign language. Out loud people say **se puede** / **no se puede**: *acá no se puede estacionar*; *¿se puede pagar con tarjeta?* Other signs you''ll meet every day: **abierto / cerrado**, **no funciona** — *out of order*, **liquidación** — *sale*, **solo efectivo** — *cash only*, **cuidado con el perro**. And to ask a shop: **¿hacen envíos?** — *do you deliver?*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('ab90d735-de35-5880-b911-2b8705709877', '6f572b83-5cbe-528d-bcdf-bbfc32e2b19c', '¿De qué laburás?', '*¿Qué hacés?* is mostly just *hi*. To ask about someone''s job, say **¿De qué laburás?** or **¿De qué trabajás?** The answer takes *de* too: *Laburo de mozo.* Or with *ser*: *Soy abogada.*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('a03e7504-87dd-5fbd-9224-ddc66e92ab9d', '731a6e56-3586-5647-a6ab-12df3dec98b6', 'Tendrías que, yo que vos', 'Day to day porteños give advice with **tendrías que** more than with *deberías*: **tendrías que descansar**. Also **yo que vos** — *if I were you*: *yo que vos, iría al médico*; or a question: **¿por qué no vas al médico?**', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('92fc2db4-2843-50a2-aab4-fa03169e8b02', '7354baf3-9248-50f2-a9bc-c31acadd98fa', 'Dos a uno', 'Scores are said with **a**: **ganamos dos a uno**, *empatamos cero a cero*. To score is **hacer un gol**: *Juan hizo dos goles*. And the pitch — and the whole stadium — is **la cancha**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('b2c4e719-dc5c-5337-87ec-23fd8cf38445', '740b6205-cb92-54dc-806f-96cc347f8ee0', 'Voy a + verb', 'For a plan, use **ir a** + the verb as it is: **voy a salir**, **¿qué vas a hacer?**, **vamos a comer**. It is how porteños talk about the future almost all the time.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('0b24bf7e-8636-5794-a6d8-1bad55a811a2', '740b6205-cb92-54dc-806f-96cc347f8ee0', 'Si', '**Si** is *if* — no accent, unlike *sí*. After it comes the plain present: **Si querés, vamos al cine.** **Si podés, salimos a la noche.**', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('8b9ca82e-4b0f-5796-877d-622de2aac40a', '76cdfd4e-984e-51cf-b109-bac7fe371aa2', 'Con Juan fuimos', '**Con Juan fuimos a la costa** means *Juan and I went to the coast* — two people, not three. Argentines say *with Juan we…* where English says *Juan and I*: **con Sofi alquilamos una carpa**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('018deba2-5088-5d2f-8ff8-700afc326cde', '776b15fe-c6a5-5aae-8876-404d392e0546', 'Devolvémelo', 'On a vos command both pronouns join the end, person first, and the stress gets a written accent: **devolvémelo** — *give it back to me*; **pasámelo** — *send it to me*; **decímelo** — *tell me*. To him or her, *le* turns into *se* again: **mandáselo**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('89462fe8-f55c-5371-aa23-378aa233d61a', '77e7e28f-74ef-5a8f-b15f-5a5589d48684', 'Le dije a Juan', 'Even when you name the person, the **le** stays: **le dije a Juan que no**, **le di la llave a Sofi**, **les mandé las fotos a mis viejos**. English says it once; a porteño says it twice. And a message is not *received*, it *reaches* you: **¿Te llegó mi audio?** — **Sí, me llegó.**', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('5877b8a4-6b4d-5004-858e-e0b6d30d2243', '7c33a900-8b22-5a9e-a34e-7c274e6a21b0', 'Fui a, me fui a', 'For where you went, porteños say **fui a** or **me fui a**: *me fui a Bariloche*, *¿adónde te fuiste en enero?* **Viajar** is for the trip itself: *viajé en micro*, *viajé sola*, *viajo mañana*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('026bd560-7714-5c78-9076-aba02a35b1d7', '7da0178d-42ee-5e98-aece-77ffbb45dd2d', 'Los cuernos', 'In real gossip nobody says *lo engañó*: it is **le metió los cuernos** — *cheated on him/her*, literally *put the horns on*. **Engañar** is also plain *to trick, to fool*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('7578114a-b5e4-5947-a129-52894ddcd1f7', '8ee9449f-672c-5e88-91cb-6db07525f370', 'Disculpá, permiso', '**Disculpá** gets a stranger''s attention: *Disculpá, ¿sos Martín?* **Permiso** is what you say to get past someone, on a full bus or in a doorway.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('da883151-76a3-53af-9ca3-7a9fd5825673', '8f8a4c97-4077-5352-b040-a22de57f1b7e', 'Colegio', 'Porteños mostly say **colegio** for school, primary or secondary: **¿A qué colegio ibas?** — *Iba a un colegio de mi barrio.* *Escuela* is understood and used too, mostly for state primary schools.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('b1798c9a-9da4-5dde-905f-9db65a0af829', '9230420b-8a48-5c4b-b9d9-b7dc3c12bb5d', 'Se lo, se la', 'Two pronouns together go person first, thing second: **me lo** mandás, **te la** doy. And *le* or *les* in front of *lo, la, los, las* turns into **se**: *¿le mandás el audio?* → **¿se lo mandás?**; *le doy la llave* → **se la doy**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('d0bec188-cd5e-5f50-8ea4-f2be488d6a42', '9cd92c11-142e-5820-ac05-2ba0eb3f623c', 'Para mí', 'To give your view, porteños say **para mí** or **me parece que**: *para mí conviene esperar*; *me parece que es caro*. **¿Qué opinás?** is the natural question; **opino que…** as an answer sounds stiff.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('b20e2e46-7d03-5dc9-be61-90cfa02a80ea', 'a6c406c0-0103-5fcc-9871-5e1bc85a3833', 'Me dio miedo', 'The other way to say how you felt is **me dio** + the feeling: **me dio miedo** — *it scared me*. You will hear it with many feelings: *me dio bronca* (it made me angry), *me dio vergüenza* (I was embarrassed), *me dio lástima* (I felt sorry).', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('16cf6d52-109f-5e35-8616-87ef244c03c7', 'ab5b06cb-0463-5884-9c6f-bc21a5b345d8', 'Ponerse a', '**Ponerse a** + a verb is *to start doing*: **nos pusimos a bailar** — *we started dancing*; **me puse a laburar** — *I got down to work*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('529fca7e-837e-5aad-a84f-b68359a3844b', 'b27a8863-2d09-52bd-992f-2a73710c019d', 'Antes… ahora', 'To say how things changed, set **antes** + the *-aba / -ía* past against **ahora** + the present: *antes era tranquilo, ahora hay mucho ruido*; *antes costaba poco, ahora es carísimo*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('919812eb-8028-5d91-b1a7-5ce140203c3c', 'b3d7d4fe-8ba0-58f9-8d0e-38b9aaf3707f', 'Elegí: two meanings', '**Elegí** is the order *choose!* and also *I chose*: **elegí el que quieras** — *pick whichever you want*; *ayer **elegí** la roja* — *yesterday I chose the red one*. The rest of the sentence tells you which.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('79ace8ff-909b-5e0d-b36a-2af4213f3056', 'b60b2d1f-25dc-5ada-9b93-a0afe7bd9a37', 'Conocer, saber', '**Saber** is to know a fact or how to do something: *sé dónde vive*. **Conocer** is to know a person or a place: **conozco a Juan**, *¿conocés Córdoba?* In the past it changes meaning: **conocí a Juan** — *I met Juan* (for the first time).', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('a1c0dd99-f02a-5bad-9b95-50478e5f3daa', 'c18ed3f6-ae4d-50fd-b360-6d7e7d73144c', 'Lo que más me gusta', 'The most natural way to say what you love about a place: **lo que más me gusta de Buenos Aires es la noche**. And the opposite: **lo que menos me gusta es el ruido**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('f43aa982-0fdb-5614-8cae-b7495273b35c', 'c72176ae-a8de-5a47-9b37-cf9bdf84de08', 'Limpio, limpia', '**Limpio** is *I clean* — and also *clean*, the opposite of *sucio*: *limpio el baño* — *el baño está limpio*, *la cocina está limpia*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('710a7b73-0b84-5feb-9047-702bbc766787', 'cc27542c-c983-52aa-88c4-8fe075eb0a0f', '¿Cómo andás?', '**¿Cómo andás?** is the everyday porteño *how are you?* — you will hear it all day. The answer is short: *Bien.* or *Todo bien.* **¿Qué onda?** gets the same answer: *¿Qué onda? — Todo bien.*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('c7048a9e-3730-5fc1-bced-2284e967b9c4', 'd7e9f660-01d8-5d0f-9136-9a85a20fc33b', 'Late, mate and the tip', 'Nobody arrives on time: **si te dicen a las nueve, llegás nueve y media**. In the mate round **gracias** means *no more for me*: **si decís gracias, no tomás más**. Men greet each other with a kiss too. And **la propina** is about ten per cent, in cash.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('28e10253-628a-56be-99ee-ea69b41f5587', 'dd303fe0-52c5-5e61-97ae-1903616e625c', 'Hace dos años que…', '**Hace dos años que vivo acá** — *I''ve been living here for two years*. Where English says *have been …ing*, Spanish stays in the present. To ask: **¿hace cuánto que vivís acá?** or just **¿hace cuánto estás acá?**; **¿hace mucho que esperás?** — *have you been waiting long?* You will also hear **llevo dos años viviendo acá** — same meaning, but day to day porteños say **hace… que**.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('aed54cfb-0f01-532e-96bf-6fc8ed773310', 'de1cac02-1435-56ef-9682-17ea2bc59bc4', 'What Migraciones asks for', 'For the **residencia** you need your **antecedentes penales** — *criminal record* — with the **apostilla**, the stamp that makes a foreign paper valid here, and a **certificado de domicilio** — *proof of address*. While you wait they give you the **precaria**, a temporary permit you can already work and travel with.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('46adada6-619f-5734-bbc8-3bc0ff3ab06b', 'e21ddcb1-102b-5c87-a018-55c861cdbe47', 'Saber or conocer?', '**Saber** + a verb is *to know how to*: **¿sabés cocinar?** For people and places use **conocer**: **conozco a Juan**, **¿conocés Palermo?** And **qué sé yo** is the porteño shrug — *who knows*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('a7acb74c-66af-5b76-bee7-4e80edc61c85', 'e7976a3a-80b3-505d-abc8-858bd6a92a90', 'La papa, la cebolla', 'For produce porteños often use the singular for the whole product: **la papa está cara** — *potatoes are expensive*; **un kilo de cebolla** — *a kilo of onions*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('9ff25831-7e96-5f7b-b336-2efe4c58e6d1', 'e89d1870-c4d1-5692-923d-5e357ae8218e', '¿Cómo estuvo?', 'To say how something was, porteños mostly use **estuvo**: *¿Cómo estuvo el partido? Estuvo bárbaro.* **Fue** works too, for events: *el recital fue bárbaro*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('95b906a1-cab6-5656-9bd4-7597c0a6238b', 'eba40ebe-93cf-52fb-a853-9a2836300617', 'When you get lost', 'Stuck on a word: **¿cómo se dice…?** — *how do you say…?* — and **¿qué significa?** — *what does it mean?* Too fast: **¿me repetís?** or **más despacio, por favor**. **No entendí** is *I didn''t get that*. And the line that buys you patience: **hablo un poco de castellano** — Argentines call the language *castellano*.', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('25308c48-0864-59fd-af07-52c38f3952eb', 'ecf3c9a9-33e3-5e2e-b2b7-aa09f082c128', 'Tostadas, un tostado', 'In a café nobody orders one slice: ask for **tostadas** — *Un café y tostadas, por favor.* **Un tostado** is something else: a toasted ham-and-cheese sandwich, the classic café lunch. *Una tostada* is one slice, at home: *¿Otra tostada?*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('4ff7f7af-b212-522a-940a-0e3fe1c83e28', 'f42f6608-6d16-5d0a-bd3f-896cd5fb4d07', 'Después, entonces', 'Tell a story in order with **primero**, **después**, **al final**: *Primero comimos, después vimos una película.* **Entonces** is mostly *so*: *No pude ir, entonces vi el partido en casa.*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('cff383cb-4819-5ddf-96be-6e4fd7823bee', 'f901adf3-4ac4-5208-8cac-9261ab754144', '¿Cómo quedamos?', 'A plan is closed with **¿Cómo quedamos?** — *so what''s the plan?* The answer fixes the time and the place: **Quedamos tipo ocho en la esquina.** Or ask straight: *¿A qué hora nos juntamos?*', 'published') on conflict do nothing;
insert into public.tips (id, unit_id, title_en, body_md, status) values ('cc5c7a5d-f22b-58e3-aa1a-28ffaa4438d9', 'f93505a1-733d-5810-85e8-c9d6ead98847', 'No hace falta que', '**No hace falta que** + subjunctive is *you do not need to*: **no hace falta que vengas hoy**. With a thing, **hace falta** is *we need*: **hace falta pan**.', 'published') on conflict do nothing;
update public.tips set title_en = '¿Funciona o no?', body_md = 'The morning after, the question is what still runs: **el subte funciona con normalidad**, or **suspendieron el servicio**. When the strike itself is called off, the fixed phrase is **levantaron el paro** / **se levantó el paro**; *suspender* is for classes, an exam, a march or a service. **Hubo un apagón** — *there was a blackout* — and the traffic lights are out: **embotellamiento**, **desvíos**, and half the city goes **a pie**.' where id = 'ee61df72-edc1-551c-8a85-ffd52d0c70ad' and body_md = 'The morning after, the question is what still runs: **el subte funciona con normalidad**, or **suspendieron el servicio**. **Hubo un apagón** — *there was a blackout* — and the traffic lights are out: **embotellamiento**, **desvíos**, and half the city goes **a pie**.';
update public.tips set title_en = 'Me prometiste', body_md = '**Me prometiste que ibas a venir** — *you promised me you''d come* (more careful: *que vendrías*). And the classic ending: **al final no vino**.' where id = '3960dc2b-904b-5a87-9ca3-02e2ae3c3968' and body_md = '**Me prometiste que vendrías** — *you promised me you''d come*. And the classic ending: **al final no vino**.';
update public.tips set title_en = '¿Por qué no me avisaste?', body_md = '*Avisar* in the past is plain -ar: **avisé**, **avisaste**, **avisó**. The text at eight-forty: **¿Dónde estás? Te esperaba a las ocho.** And the answer, always: **ya salgo**. The other classics: **estoy llegando** (still ten minutes away), **estoy en camino** — *I''m on my way* — and **llego en diez**.' where id = '3c539a2a-3a6b-501b-8da7-a0d344dac0f0' and body_md = '*Avisar* in the past is plain -ar: **avisé**, **avisaste**, **avisó**. The text at eight-forty: **¿Dónde estás? Te esperaba a las ocho.** And the answer, always: **ya salgo**.';
update public.tips set title_en = 'Se instalaron', body_md = 'The family story runs in the third person plural: **se escaparon de la guerra**, **se instalaron en un conventillo** — *a crowded tenement house* — and **trabajaron en el puerto**. One person: **se instaló**. They left **pobreza** behind, **mantuvieron** the language and the traditions, and **guardaron** the photos of the ship. *Conservaron* says the same, but it is a written word.' where id = '4039fa21-f933-5aec-877d-701a109a210b' and body_md = 'The family story runs in the third person plural: **se escaparon de la guerra**, **se instalaron en un conventillo** — *a crowded tenement house* — and **trabajaron en el puerto**. One person: **se instaló**. They left **pobreza** behind and **conservaron** the recipes.';
update public.tips set title_en = 'Es cualquiera', body_md = '**Es cualquiera** — *that''s nonsense*; **dijo cualquiera** — *he talked nonsense*; **hizo cualquiera** — *he did something stupid*. **Flasheaste** — *you''re imagining things*. And a **¡qué lindo!** can be sincere, or ironic when the rain starts.' where id = '6f7a19a0-4270-5d35-a772-7ff0d5c9059c' and body_md = '**Es cualquiera** — *that''s nonsense*. **Flasheaste** — *you''re imagining things*. And a **¡qué lindo!** can be sincere, or ironic when the rain starts.';
update public.tips set title_en = 'At the doctor''s', body_md = 'You ask for a **turno** (an appointment), and the verb is **sacar turno**: *tengo que sacar turno con el médico*. The **guardia** is the emergency room. **Estoy engripado** — *I''ve got the flu* — is what gets you the day off.' where id = 'd389c9c5-149a-57c8-b192-f1851fa1b7df' and body_md = 'You ask for a **turno** (an appointment); the **guardia** is the emergency room. **Estoy engripado** — *I''ve got the flu* — is what gets you the day off.';
update public.tips set title_en = 'Suelo', body_md = '**Soler** is *to usually*: **suelo almorzar tarde** — *I usually have lunch late*; **¿solés venir acá?** It only ever comes with an infinitive. In speech porteños more often say **generalmente** or **casi siempre**: **generalmente almuerzo tarde**.' where id = 'd578e8dc-eaae-5236-b408-a7b053f9755a' and body_md = '**Soler** is *to usually*: **suelo almorzar tarde** — *I usually have lunch late*; **¿solés venir acá?** It only ever comes with an infinitive.';
update public.tips set title_en = 'De golpe, para colmo', body_md = 'The twist arrives **de golpe** — *all of a sudden* — or **de la nada** — *out of nowhere*. **Para colmo** stacks one more thing on top, like **encima**: **para colmo, llovía**. **Por lo visto** — *apparently* — is what you say when you weren''t there. When someone loses a job, people say **lo echaron**; **lo despidieron** is the word of the news and of HR.' where id = 'c1cd73a8-a9a9-5e11-a3b5-76f0696539c4' and body_md = 'The twist arrives **de golpe** — *all of a sudden* — or **de la nada** — *out of nowhere*. **Para colmo** stacks one more thing on top, like **encima**: **para colmo, llovía**. **Por lo visto** — *apparently* — is what you say when you weren''t there.';
update public.tips set title_en = 'The long goodbye', body_md = 'A porteño goodbye is several: **bueno, nos hablamos**, **cuidate**, **un beso**, **que descanses** — and then another *chau* at the door. **Un abrazo** — or just **abrazo** — is the usual sign-off, especially between men: **dale, abrazo**; **chau, un abrazo**.' where id = 'c5e7d696-e96e-5262-abd7-c802b8a68a8d' and body_md = 'A porteño goodbye is several: **bueno, nos hablamos**, **cuidate**, **un beso**, **que descanses** — and then another *chau* at the door.';
update public.tips set title_en = 'Me reí', body_md = '**Reírse** is *to laugh*: **me río mucho con vos** — *I laugh a lot with you*; **me reí un montón**, **nos reímos de todo**; **¿te reíste?** **Llorar** is *to cry*: **lloré con la película**.' where id = '8845c3ad-88ce-52bb-b23a-7f37ca96a528' and body_md = '**Reírse** is *to laugh*: **me reí un montón**, **nos reímos de todo**. **Llorar** is *to cry*: **lloré con la película**.';
update public.tips set title_en = 'Pedir', body_md = '**Pido** (I order), **pedís** (you order); in the past **pedí**, **pediste**, and — with an *i* — **pidió**. At the table: **¿Me traés la carta?** and, at the end, **la cuenta**. To get in: **Una mesa para dos, por favor.** And water is **con gas** or **sin gas**: *Para tomar, un agua sin gas.*' where id = '63f495cd-a71f-55ee-ae30-b4789e91cebd' and body_md = '**Pido** (I order), **pedís** (you order); in the past **pedí**, **pediste**, and — with an *i* — **pidió**. At the table: **¿Me traés la carta?** and, at the end, **la cuenta**.';
update public.tips set title_en = 'Picking a side', body_md = 'All the way with you: **exacto**, **totalmente**, **obvio**, **sin duda** — and the stiffer **coincido**. All the way against: **al contrario**, **no creo**, **estás equivocado**. And for the friend who goes too far: **¡no exageres!**' where id = 'abc22894-4d33-582c-ba69-497c6215889e' and body_md = 'All the way with you: **exacto**, **coincido**, **sin duda**. All the way against: **al contrario**. And for the friend who goes too far: **¡no exageres!**';
update public.tips set title_en = 'The summer visitor', body_md = 'A hot night, a **cucaracha** in the kitchen, and it **vuela**: **grité**, **pegué un salto** — more natural than a bare *salté* — and in the end **la maté** with an **ojota**. Every porteño has this story. The other summer visitor is the **mosquito**: **me picó un mosquito**, so nobody goes out without **repelente**.' where id = 'f4296b31-e5fc-50a1-a8e5-b7b5d36a9830' and body_md = 'A hot night, a **cucaracha** in the kitchen, and it **vuela**: **grité**, **salté**, and in the end **la maté** with an **ojota**. Every porteño has this story.';
update public.tips set title_en = 'Christmas in summer', body_md = '**Las fiestas** are Christmas and New Year together: *¡Felices fiestas!* **Navidad** falls in the heat and is celebrated the night before, on **Nochebuena** — the 24th: an *asado* or a cold spread, and at midnight **sidra**, **pan dulce** and a **brindis** — *¡salud!* — before the fireworks and **Papá Noel**.' where id = 'a3d8add9-3af2-5335-9dc3-fda0446ac1a7' and body_md = '**Navidad** falls in the heat, so it is often an *asado*, cider and **pan dulce** at midnight, and a **brindis** — *¡salud!* — before the fireworks.';
update public.tips set title_en = 'Me llegó una cadena', body_md = 'The family WhatsApp group sends a **cadena** — *a chain message* — every morning. **Chequeá la fuente** before you believe it — and before **compartirlo**. If it isn''t true: **es mentira**, **es falso** or, very porteño, **es verso** — *it''s made up*.' where id = 'df9ba005-f0db-553b-a492-50b1f5d3f3ce' and body_md = 'The family WhatsApp group sends a **cadena** — *a chain message* — every morning. **Chequeá la fuente** before you believe it.';
update public.tips set title_en = 'Gramos, litros', body_md = 'At the fiambrería you buy by the **gramo**: **cien gramos de jamón**, cut in **fetas** — *slices*. Milk comes by the **litro**. At the **feria**, the street market, it''s still the kilo: **medio kilo de frutillas**. The classic deli order is **un cuarto** — 250 grams: **un cuarto de jamón cocido**. **Jamón cocido** is plain ham; **jamón crudo** is the cured one.' where id = '3d839f10-580b-59a4-ae50-d6b91d794967' and body_md = 'At the fiambrería you buy by the **gramo**: **cien gramos de jamón**, cut in **fetas** — *slices*. Milk comes by the **litro**. At the **feria**, the street market, it''s still the kilo: **medio kilo de frutillas**.';
update public.tips set title_en = '¿Escuchaste?', body_md = '**¿Escuchaste la radio?** — the vos past, like *leíste*. And a tip from someone who knows is **un dato**: *me pasaron el dato*. Gossip opens with **¿viste que…?** — *did you hear that…?*: **¿viste que Juan renunció?**' where id = '375791dd-270a-541e-90ed-5b241e5fb3d0' and body_md = '**¿Escuchaste la radio?** — the vos past, like *leíste*. And a tip from someone who knows is **un dato**: *me pasaron el dato*.';
update public.tips set title_en = 'Se apagó, se colgó', body_md = 'A machine that fails on its own takes **se** and the preterite, like **se cortó**: **se apagó** — *it switched off*; **se colgó** — *it froze*. Your friend **se quedó sin batería**? Now you know why she didn''t answer. When anything stops working, porteños say it **no anda**: **no anda el wifi**, **no me anda el celu**. The universal fix: **apagalo y prendelo**.' where id = 'ecc14597-b02a-597b-bcbf-15a4de418dbf' and body_md = 'A machine that fails on its own takes **se** and the preterite, like **se cortó**: **se apagó** — *it switched off*; **se colgó** — *it froze*. Your friend **se quedó sin batería**? Now you know why she didn''t answer.';
update public.tips set title_en = 'Vencido', body_md = 'A document that has run out is **vencido**: *tengo el pasaporte vencido*. You renew it (**renovar**), fill in the form — **completar el formulario**: *ya completé el formulario* —, stand in line — **hacer la cola**; you will also hear **fila** — and sign (**firmar**).' where id = '69d02752-e744-5eaf-b2d3-5ee433c31092' and body_md = 'A document that has run out is **vencido**: *tengo el pasaporte vencido*. You **renovás** it, fill in a **formulario**, wait in the **fila**, and **firmás**.';
update public.tips set title_en = 'Hola, Juan:', body_md = 'Most work emails open with **Hola, Juan:** or **Buen día, Sofi:** and close with **Saludos**, **Abrazo** or **Un abrazo**. **Estimado Juan** / **Estimada Sofi** is the formal exception, and so is **quedo atento** (a woman: **quedo atenta**) — *I look forward to your reply*. **Te adjunto** is *I''m attaching*: *te adjunto mi CV*; **desde ya, gracias** is *thanks in advance*.' where id = 'e06c9bfd-3dd2-5980-a26d-595cd6ecb929' and body_md = 'A work email opens with **Estimado Juan** or **Estimada Sofi** and ends with **Saludos**. **Te adjunto** is *I''m attaching*; **desde ya, gracias** is *thanks in advance*.';
update public.tips set title_en = 'El de, la de', body_md = 'Drop the noun, keep the article: **el de la vidriera** — *the one in the window*; **la de la izquierda** — *the one on the left*; **las de** allá. With a name it is *someone''s*: **el de Lucía** — *Lucía''s*. With people it is *the guy in, the people from*: **el de rojo** — *the guy in red*; **los de arriba** — *the people upstairs*. It matches what it stands for, like *el que*: **la que te probaste**.' where id = 'd4f3c5be-cc6e-55ca-b459-5f8dcfb65deb' and body_md = 'Drop the noun, keep the article: **el de la vidriera** — *the one in the window*; **la de la izquierda** — *the one on the left*; **las de** allá. It matches what it stands for, like *el que*: **la que te probaste**.';
update public.tips set title_en = 'Sí, claro', body_md = 'Said slowly, **sí, claro** means *yeah, right*. **¡Qué novedad!** — *what a surprise* — is for the bondi that''s late again; **¡lo que faltaba!** — *that''s all we needed* — for the rain that starts on top of it. The everyday ones: **qué raro**, said flat — *¿llegó tarde? Qué raro.* — and **mirá vos** — *well, look at that*. The tone does the work.' where id = 'bb2b8f8c-6dae-5623-9c59-9a450c30bb65' and body_md = 'Said slowly, **sí, claro** means *yeah, right*. **¡Qué novedad!** — *what a surprise* — is for the bondi that''s late again; **¡lo que faltaba!** — *that''s all we needed* — for the rain that starts on top of it. The tone does the work.';
update public.tips set title_en = 'Un montón', body_md = '**Gracias por todo**, **mil gracias**, **gracias un montón** — the thanks gets bigger, the grammar doesn''t change. Outside the thanks it is everywhere: **un montón de** + noun is *loads of* — **hay un montón de gente**, **tengo un montón de laburo** — and **me gusta un montón**.' where id = '85eeb729-9ee3-5ef6-a492-6eadc3ca5fdf' and body_md = '**Gracias por todo**, **mil gracias**, **gracias un montón** — the thanks gets bigger, the grammar doesn''t change.';
update public.tips set title_en = '¿A qué altura?', body_md = 'Porteños give an address as street and number — *Corrientes 1500* — and ask **¿a qué altura?** to know which block. The number goes up about a hundred every **cuadra**. To ask the way: **¿Cómo llego a la estación?** — *how do I get to the station?*' where id = '6b5e4dd1-32f1-5210-99e2-f0e00d40b4cb' and body_md = 'Porteños give an address as street and number — *Corrientes 1500* — and ask **¿a qué altura?** to know which block. The number goes up about a hundred every **cuadra**.';
update public.tips set title_en = 'Ganamos, perdimos', body_md = 'After a match it''s **ganamos**, **perdimos** or **empatamos** — *we* won, even if you were on the sofa. The first football question you will get in Argentina: **¿De qué equipo sos?** — **Soy de Boca.** **Soy de River.** Which one, the course leaves to you.' where id = '7fe05051-cb0d-51d1-a483-3d0d35b01aa0' and body_md = 'After a match it''s **ganamos**, **perdimos** or **empatamos** — *we* won, even if you were on the sofa. The course leaves the club to you.';
update public.tips set title_en = 'Se me bloqueó', body_md = 'The bank has its own accidents: **se me bloqueó la tarjeta**, **se me venció la tarjeta**. Same *se me* as a dropped glass. How it happens: **puse mal la clave tres veces** — *I entered the wrong PIN three times*.' where id = '4b021c65-ffd3-5b07-9dea-dd8581d6491b' and body_md = 'The bank has its own accidents: **se me bloqueó la tarjeta**, **se me venció la tarjeta**. Same *se me* as a dropped glass.';
update public.tips set title_en = 'Capital y provincia', body_md = 'The city is **la Capital**; the ring of towns around it, in the province, is **el conurbano**. Palermo, San Telmo and La Boca are all barrios of the Capital. Each barrio has its thing: **Palermo está lleno de bares**, **en San Telmo hay una feria los domingos**, **La Boca es re turística**. The first question to any porteño: **¿en qué barrio vivís?**' where id = '9b2c23e3-838a-574f-affd-f711c01a05fe' and body_md = 'The city is **la Capital**; the ring of towns around it, in the province, is **el conurbano**. Palermo, San Telmo and La Boca are all barrios of the Capital.';
update public.tips set title_en = 'Suggest, and say no nicely', body_md = '**Podríamos ir al cine** — *we could go to the movies*. **Nos convendría salir temprano** — *we''d better leave early*. Turning it down: **preferiría ir otro día**. Saying yes: between friends it is **dale** or **obvio** — **obvio, te ayudo**. **Con gusto** is the formal one, what you hear in a shop.' where id = 'a1ed21d8-6f6f-54a3-8bb5-3a6585fe6f0e' and body_md = '**Podríamos ir al cine** — *we could go to the movies*. **Nos convendría salir temprano** — *we''d better leave early*. Turning it down: **preferiría ir otro día**. Saying yes: **con gusto**.';
update public.tips set title_en = 'Me robaron', body_md = '**Me robaron el celu** — *my phone got stolen*, literally *they stole the phone from me*. The thief is a **chorro** in lunfardo, a **ladrón** in the news. On the subte it is usually a **punga** — *a pickpocket* — and you notice later. **Me asaltaron** is worse: they robbed you face to face.' where id = '3aedcd83-cbf5-5910-98dc-1008087f4635' and body_md = '**Me robaron el celu** — *my phone got stolen*, literally *they stole the phone from me*. The thief is a **chorro** in lunfardo, a **ladrón** in the news.';
update public.tips set title_en = '¿De qué cuadro sos?', body_md = 'The first question in a new friendship. A team is a **cuadro**, and you don''t choose it, you inherit it: **soy del mismo cuadro que mi viejo**. The answer is **soy de** or **soy hincha de**: *Soy de Racing.* *Soy hincha de River.* **Hinchar por** is for one game or the national team: **¿por quién hinchás?** — *Hincho por Argentina.*' where id = 'bb6b163b-1fc3-54dd-91e3-016a0d3e09ba' and body_md = 'The first question in a new friendship. A team is a **cuadro**, and you don''t choose it, you inherit it: **soy del mismo cuadro que mi viejo**. To root for one is **hinchar por**: **¿por quién hinchás?**';
update public.tips set title_en = 'El superclásico', body_md = 'The two biggest teams, **Boca** and **River**, playing each other is **el superclásico**; any derby is a **clásico** — *Racing* against *Independiente*, for one. Boca fans are called *bosteros* and River fans *gallinas*: insults they now wear with pride. The fans stand on the **tribuna**. Which side you''re on, the course leaves to you.' where id = '8f4c23b2-5684-59ec-a311-4cb9e59ce5a6' and body_md = 'The two biggest teams playing each other is **el superclásico**; any derby is a **clásico**. The fans stand on the **tribuna**. Which side you''re on, the course leaves to you.';
update public.tips set title_en = 'Me voy', body_md = '*Voy* is where you''re going; **me voy** is that you''re leaving: *me voy a las ocho*. *¿Te vas?* — *Sí, me voy.* And when someone is slow to leave: **¡Dale, apurate!** — *come on, hurry up!*' where id = 'edcf0fa6-099e-5614-a334-06948ab92092' and body_md = '*Voy* is where you''re going; **me voy** is that you''re leaving: *me voy a las ocho*. *¿Te vas?* — *Sí, me voy.*';
update public.tips set title_en = 'La siesta', body_md = '**Dormir** stretches like *poder*: **duermo**, but **dormís**. And **la siesta** after lunch is still sacred in much of the country — less so in Buenos Aires. Around five comes the fourth meal: to **merendar** — mate or coffee with something sweet.' where id = 'c46ddd6d-9641-5450-a73f-0dad03d20e44' and body_md = '**Dormir** stretches like *poder*: **duermo**, but **dormís**. And **la siesta** after lunch is still sacred in much of the country — less so in Buenos Aires.';
update public.tips set title_en = 'At the farmacia', body_md = 'Half the time the pharmacist is your doctor: **estoy resfriado**, **tengo alergia**, **me duele el oído** — and you leave with **una curita** or **unas pastillas**. To ask: **¿Tenés algo para la alergia?** — **Necesito algo para la garganta.** A broken bone is **quebrado**: *tiene el brazo quebrado*. And when you hurt yourself: **me lastimé la rodilla**.' where id = 'be9c362e-6f84-5899-8e49-6046ba3c3cf3' and body_md = 'Half the time the pharmacist is your doctor: **estoy resfriado**, **tengo alergia**, **me duele el oído** — and you leave with **una curita** or **unas pastillas**.';
update public.tips set title_en = '¿Te alcanza?', body_md = '*No me alcanza* for you is **¿te alcanza?** — *do you have enough?*. **Cobré** — *I got paid*; **¿gastás mucho?**, **¿ahorrás algo?** — vos adds **-ás**. For everyone at work: **cobramos el lunes** — *we get paid on Monday*.' where id = '9a9f029d-8897-58a1-862d-3762db0207f1' and body_md = '*No me alcanza* for you is **¿te alcanza?** — *do you have enough?*. **Cobré** — *I got paid*; **¿gastás mucho?**, **¿ahorrás algo?** — vos adds **-ás**.';
update public.tips set title_en = 'Arriba, abajo, adentro', body_md = 'Three words that need nothing after them: **arriba** (up, upstairs), **abajo** (down, downstairs), **adentro** (inside). *Estoy abajo* is what a porteño texts from the street when they''re at your door. The fourth one is **afuera** — *outside*: *mi auto está afuera*.' where id = '0f108707-6528-5552-95c5-9202ab24e0d7' and body_md = 'Three words that need nothing after them: **arriba** (up, upstairs), **abajo** (down, downstairs), **adentro** (inside). *Estoy abajo* is what a porteño texts from the street when they''re at your door.';
update public.tips set title_en = 'Planta baja', body_md = 'The ground floor is **la planta baja**; the one above it is *el primer piso*. Ringing from the street, you press the **timbre** with the floor and the letter: *4° B*. Out loud, *4° B* is **cuarto B**: *vivo en el cuarto B*. The first five floors: **primero, segundo, tercero, cuarto, quinto** — and *primero* loses its *-o* before a noun: *el **primer** piso*.' where id = 'd8622385-5e4a-5495-9a55-b9f96b8c8aeb' and body_md = 'The ground floor is **la planta baja**; the one above it is *el primer piso*. Ringing from the street, you press the **timbre** with the floor and the letter: *4° B*.';
update public.tips set title_en = 'Al horno, al pedo', body_md = '**Estoy al horno** — *I''m in trouble, I''m toast*. **Qué bajón** — *what a downer*. **Al pedo** — *for nothing, doing nothing*: **fui al pedo**, **estoy al pedo**. And the flat *no way*: **ni en pedo**. The other *pedo* phrases: **estar en pedo** — *to be drunk*; **de pedo** — *by pure luck*: *llegué de pedo*; **a los pedos** — *very fast*. Among friends only.' where id = '1db93231-c31c-5630-a9d7-a5c19c863dd1' and body_md = '**Estoy al horno** — *I''m in trouble, I''m toast*. **Qué bajón** — *what a downer*. **Al pedo** — *for nothing, doing nothing*: **fui al pedo**, **estoy al pedo**. And the flat *no way*: **ni en pedo**. Among friends only.';
update public.tips set title_en = 'Medio, re', body_md = 'Porteños grade a person with two little words: **re** turns it up — *es re generosa* — and **medio** turns it down — *es medio vago*, *he''s a bit lazy*. **Medio** never changes: *medio tonta*, *medio serios*. And the verb matters: **es callado** — *he is a quiet guy* — is what he is like; **está callado** — *he is quiet today* — is how he is right now. Same with **es serio** and **estás serio**.' where id = '411110dd-943a-5910-bf5f-9a7c66ad7eef' and body_md = 'Porteños grade a person with two little words: **re** turns it up — *es re generosa* — and **medio** turns it down — *es medio vago*, *he''s a bit lazy*. **Medio** never changes: *medio tonta*, *medio serios*.';
update public.tips set title_en = 'The good and the bad', body_md = '**Macanudo** is the old-school *great guy* — you will hear it from older people; under fifty it is **copado** or **piola**, and **es una genia** for a woman who is great at what she does; **trabajador** is *hard-working*. **Agrandado** is *full of himself*, **egoísta** *selfish* — and *egoísta* is the same for him and for her, like *inteligente*.' where id = '3cf567c2-f4d8-5988-b290-df55a3a1ea54' and body_md = '**Macanudo** is the old-school *great guy*; **trabajador** is *hard-working*. **Agrandado** is *full of himself*, **egoísta** *selfish* — and *egoísta* is the same for him and for her, like *inteligente*.';
update public.tips set title_en = '¿Te acordás?', body_md = '**¿Te acordás cuando…?** opens every memory at a family asado. **Me acuerdo** — *I remember*; **no me acuerdo** — *I don''t remember*. The moment it comes back is the past: **¡ah, ahora me acordé!**; **¿te acordaste de llamar?** — *did you remember to call?*' where id = 'ce04f326-dc62-5b78-b284-566e6fd63f08' and body_md = '**¿Te acordás cuando…?** opens every memory at a family asado. **Me acuerdo** — *I remember*; **no me acuerdo** — *I don''t remember*.';
update public.tips set title_en = 'Antes era distinto', body_md = '**Antes era distinto** — *it used to be different*. **¡Qué épocas!** — *those were the days!* — closes it. With *ser* it is a different kind of thing: **el barrio era distinto**. With *estar* it has changed: **estás distinta** — *you look different*.' where id = 'f03770e9-f70b-5bf7-9fc5-3507aa771946' and body_md = '**Antes era distinto** — *it used to be different*. **¡Qué épocas!** — *those were the days!* — closes it.';
update public.tips set title_en = 'Months and degrees', body_md = 'Months have no capital: **en marzo**, **en diciembre**. Temperature is **grados**: *hace treinta y cinco grados* is a normal January day, and porteños blame everything on **la humedad**. Argentina uses Celsius: *35 grados* is very hot (95°F), and *1 grado* is almost freezing.' where id = 'f30ace7e-6e7e-53a8-8879-9f8494a8c3ef' and body_md = 'Months have no capital: **en marzo**, **en diciembre**. Temperature is **grados**: *hace treinta y cinco grados* is a normal January day, and porteños blame everything on **la humedad**.';
update public.tips set title_en = 'La garantía', body_md = 'Renting in Buenos Aires means the **inmobiliaria** asks for a **garantía** — a relative''s property as a guarantee — and a **contrato**. Foreigners usually take an **alquiler temporario** — *a short-term rental*, **amoblado** — or pay a **seguro de caución** instead of the garantía, plus a **depósito**. Ask about the **expensas** (the monthly building fees) and how many **ambientes** it has: *un dos ambientes* is one bedroom and a living room. Some **dueños** don''t take **mascotas**.' where id = 'b52a18e2-e627-5862-85be-cadba86191d4' and body_md = 'Renting in Buenos Aires means the **inmobiliaria** asks for a **garantía** — a relative''s property as a guarantee — and a **contrato**. Some **dueños** don''t take **mascotas**.';
update public.tips set title_en = 'Llegaron en barco', body_md = 'Most porteños have an **abuelo** or **bisabuelo** who **llegó en barco** from Italy or Spain. An Italian, or anyone with an Italian surname, is a **tano** or a **tana**: *mi abuelo era tano*. That''s why a porteño talks with his hands and eats ñoquis on the 29th.' where id = 'a5efa082-ec6d-55de-8585-829fc1b6a047' and body_md = 'Most porteños have an **abuelo** or **bisabuelo** who **llegó en barco** from Italy or Spain. That''s why a porteño talks with his hands and eats ñoquis on the 29th.';
update public.tips set title_en = 'Mejor todavía', body_md = '**Mejor todavía** — *even better*: **¿es gratis? Mejor todavía**; also **mejor así** — *better this way*. *Tanto mejor* says the same but sounds bookish. To **evitar** the **hora pico**, you go early; the place **se llena** fast; and leaving early, the day **rinde** — *goes further*.' where id = 'b9bc5c55-0b39-5996-a6ed-71dd17a76fb0' and body_md = '**Tanto mejor** — *all the better*: **¿no viene nadie? Tanto mejor**. To **evitar** the **hora pico**, you go early; the place **se llena** fast; and leaving early, the day **rinde** — *goes further*.';
update public.tips set title_en = '¡Cuidado!', body_md = '**¡Cuidado!** — *careful!* — or the full **tené cuidado**: **tené cuidado con la billetera en el subte**. The tips that come with it: **no uses el celu en la calle**, **no tomes taxi para todo**, **es mejor que pagues en efectivo**, **te conviene reservar**.' where id = 'c25e8bf6-8957-58ac-8fc3-5770ed6b1bef' and body_md = '**¡Cuidado!** — *careful!* — and the tips that come with it: **no uses el celu en la calle**, **es mejor que cambies plata antes**, **te conviene reservar**.';
update public.tips set title_en = '¿Te convido?', body_md = '**Convidar** is *to offer, to share what''s yours*: **¿te convido un mate?**, **convidame uno**. Afternoon **merienda** means mate with **bizcochitos**, or **tortas fritas** when it rains. A **matero** drinks it all day; kids get **mate cocido**, the tea-bag version. To ask for one, the question is kinder than the order: **¿me convidás un mate?** *Convidame* is for close friends.' where id = 'a27610da-e63d-5d19-9150-fec8001c9793' and body_md = '**Convidar** is *to offer, to share what''s yours*: **¿te convido un mate?**, **convidame uno**. Afternoon **merienda** means mate with **bizcochitos**, or **tortas fritas** when it rains. A **matero** drinks it all day; kids get **mate cocido**, the tea-bag version.';
update public.tips set title_en = 'Estaba or me puse?', body_md = '**Estaba nervioso** is how you were; **me puse nervioso** is the moment it hit you. **Me sentí re mal** — *I felt awful* — is one moment too. For *us*: **nos pusimos contentos**; and **me puse colorado** is *I blushed*. About someone else: **¿cómo se sintió tu vieja?**' where id = '80ff4fcc-3b03-5cec-bc11-61a64e3a76c3' and body_md = '**Estaba nervioso** is how you were; **me puse nervioso** is the moment it hit you. **Me sentí re mal** — *I felt awful* — is one moment too. For *us*: **nos pusimos contentos**; and **me puse colorado** is *I blushed*.';
update public.tips set title_en = 'La primaria', body_md = 'School here is **la primaria** (six to twelve) and then **la secundaria**. In a state school everyone wears a white **guardapolvo** over their clothes, and the best part of the day is the **recreo**. In primaria the teacher is **la maestra** or **el maestro**; from secundaria on it is **el profesor**, **la profe**. Each year of primaria is a **grado**: *primer grado*.' where id = 'a4adbfa9-faf6-51e4-b4d1-cd956aff9126' and body_md = 'School here is **la primaria** (six to twelve) and then **la secundaria**. In a state school everyone wears a white **guardapolvo** over their clothes, and the best part of the day is the **recreo**.';
update public.tips set title_en = 'Encantado, encantada', body_md = '**Encantado** — *delighted* — is what you say when you meet someone, and it matches whoever is speaking: a man says *encantado*, a woman **encantada**. The reply: **igualmente** — *likewise*. Day to day, most porteños just say **un gusto** or *mucho gusto*: *Soy Sofi.* — *Un gusto, Sofi.*' where id = 'dce725f6-bc10-516a-85c8-df10e2a4e81f' and body_md = '**Encantado** — *delighted* — is what you say when you meet someone, and it matches whoever is speaking: a man says *encantado*, a woman **encantada**. The reply: **igualmente** — *likewise*.';
update public.tips set title_en = 'Hinchamos por el mismo', body_md = '**Hinchar por** runs in the family: **en casa hinchamos todos por el mismo cuadro**; **de chico hinchaba por otro, pero mi viejo no me dejó**. A fan **de toda la vida** never changes club — changing wife is easier, they say. Day to day, people simply say **somos del mismo cuadro**.' where id = '221c8d0b-ad2b-59ef-9e73-229943384be9' and body_md = '**Hinchar por** runs in the family: **en casa hinchamos todos por el mismo cuadro**; **de chico hinchaba por otro, pero mi viejo no me dejó**. A fan **de toda la vida** never changes club — changing wife is easier, they say.';
update public.tips set title_en = 'Me da cosa', body_md = '**Me da cosa** — *I feel awkward about it, it makes me uneasy*. Mostly with an infinitive: **me da cosa pedirle plata** — *I feel bad asking him for money*; and about a thing: *ese perro me da cosa*. **Me pone mal** — *it gets me down*. **Me quedé con las ganas** — *I missed out, and I still want to*.' where id = '6b55c1f4-870b-5f43-8afa-9decf186dca1' and body_md = '**Me da cosa** — *it makes me uneasy, I don''t feel right about it*. **Me pone mal** — *it gets me down*. **Me quedé con las ganas** — *I missed out, and I still want to*.';
update public.tips set title_en = 'Quisiera, ¿no tendrás…?', body_md = 'Day to day porteños soften a request with **quería**: **quería un turno para mañana**, **te quería pedir algo**. **Quisiera** — *I would like* — is the formal one, for the phone or an office: **quisiera un turno**; nobody orders food with it. To ask a stranger for something, add **no** and the future: **¿no tendrás hora?** — *you would not have the time?*' where id = '1d87549c-7542-53ad-8a97-9ed8aef021a6' and body_md = 'The politest way to ask is **quisiera** — *I''d like*: **quisiera un turno**. To ask a stranger for something, add **no** and the future: **¿no tendrás hora?** — *you wouldn''t have the time?*';
update public.tips set title_en = 'Me arrepiento', body_md = '**Me arrepiento** — *I regret it*; **me arrepentí** — *I regretted it, I changed my mind*. With what you did or didn''t do, **de (no) haber** + participle: **me arrepiento de no haber ido** — *I regret not going*; *no me arrepiento de haber venido*. A missed chance is a **oportunidad** you didn''t **aprovechar**.' where id = '8a29fec5-b96f-5019-8de7-6e3c598a5302' and body_md = '**Me arrepiento** — *I regret it*; **me arrepentí** — *I regretted it, I changed my mind*. A missed chance is a **oportunidad** you didn''t **aprovechar**.';
update public.tips set title_en = 'La parrillada', body_md = 'For the table there''s the **parrillada** — *a mixed grill* on its own little grill: chorizo, morcilla, **mollejas** — *sweetbreads: a soft gland, not bread* — **chinchulines** and a **tira de asado**. On your own: a **bife de chorizo** or an **entraña**. The classic start is a **provoleta para compartir**; the prized cuts are **ojo de bife** and **lomo**, with *papas fritas* or *ensalada* on the side.' where id = '320ccab5-810e-5019-b4e8-625dde6a8ac3' and body_md = 'For the table there''s the **parrillada** — *a mixed grill* on its own little grill: chorizo, morcilla, **mollejas** — *sweetbreads: a soft gland, not bread* — **chinchulines** and a **tira de asado**. On your own: a **bife de chorizo** or an **entraña**.';
update public.tips set title_en = 'Se recibió, se jubiló', body_md = '| Mi hermano **se recibió** de abogado. | graduated |
| **Me recibí** el año pasado. | I graduated |
| **Se comprometieron** en marzo. | they got engaged |
| Mi tía **se jubiló**. | retired |
| Mi abuelo **se murió** en mayo. | died |

Life''s big steps take the pronoun, like **se casó**: *me*, *se*, always in front. Ask **¿de qué te recibiste?** — *what did you graduate in?* And **se murió** is for talking among friends; to the family you say **falleció** — *passed away*.' where id = '164a4c51-f39c-5285-b76f-97464dab857a' and body_md = '| Mi hermano **se recibió** de abogado. | graduated |
| **Me recibí** el año pasado. | I graduated |
| **Se comprometieron** en marzo. | they got engaged |
| Mi tía **se jubiló**. | retired |
| Mi abuelo **se murió** en mayo. | died |

Life''s big steps take the pronoun, like **se casó**: *me*, *se*, always in front.';
update public.tips set title_en = 'Se calentó', body_md = 'The joke only works if nobody takes it badly: **se calentó** — *he got mad* — and **se ofendió** — *he took offense* — are the worst things to say about someone at an asado. **Se picó** is what porteños say when a match or an argument got heated: *se picó el partido*. Everybody has an **apodo** — *a nickname*: **el Flaco**, **el Gordo**, **el Negro**, **el Pelado**, **el Colo** (the redhead). They are friendly, not insults: *le dicen el Flaco*. A **broma** — *a prank* — is a sign of affection too. **No te hagas el vivo**, though: **te hacés el vivo** is *you''re trying to be clever, to take advantage of someone*.' where id = 'a3dfd806-54f5-516a-a10e-12f1e87569d8' and body_md = 'The joke only works if you don''t **picarse** — *get touchy*: **se picó** is the worst thing to say about someone at an asado. Everybody has an **apodo** — *a nickname* — and a **broma** — *a prank* — is a sign of affection. **No te hagas el vivo**, though: **te hacés el vivo** is *you''re trying to be clever, to take advantage of someone*.';
update public.tips set title_en = 'Penales', body_md = 'A **final** that ends in a tie goes first to the **alargue** — *extra time* — and then to **penales**: the **arquero atajó** one, somebody **metió** the last, and the whole city is out in the street in the **camiseta**. A great goal is a **golazo**. **Salir campeón** is *to win the title*; **¿cómo salieron?** asks how the game ended. What you shout: **¡Vamos, Argentina!** and **¡Aguante!** with your team: *¡Aguante Boca!* And a referee who gets everything wrong **no pega una**.' where id = '0543a4d4-e086-5583-a92b-a63cb2d2b3c0' and body_md = 'A **final** that ends in a tie goes to **penales**: the **arquero atajó** one, somebody **metió** the last, and the whole city is out in the street in the **camiseta**. A great goal is a **golazo**. **Salir campeón** is *to win the title*; **¿cómo salieron?** asks how the game ended.';
update public.tips set title_en = 'Por si', body_md = 'Unlike *a menos que*, **por si** — *just in case* — keeps the normal verb. It''s what people say for everyday precautions: **llevá paraguas por si llueve**; *te dejo las llaves por si llegás antes*. Short version: **por las dudas** — *llevá paraguas, por las dudas*.' where id = '68fde42c-f91d-5e04-87d5-3b54e0e196fc' and body_md = 'Unlike *a menos que*, **por si** — *just in case* — keeps the normal verb: **llevá paraguas por si llueve**. Short version: **por las dudas**.';
update public.tips set title_en = 'Acabo de', body_md = '**Acabo de** + infinitive is *I just did it*: **acabo de llegar**, **acaba de salir**. Porteños mostly say **recién** + the past instead: **recién llegué**, **recién salió** — it means the same. **Volví a** is *I did it again*: **volví a perder las llaves**. Or just **de nuevo** or **otra vez** — *again*.' where id = '043bf160-0648-51c6-bec2-2b7afbcb4c4a' and body_md = '**Acabo de** + infinitive is *I just did it*: **acabo de llegar**, **acaba de salir**. **Volví a** is *I did it again*: **volví a perder las llaves**. Or just **de nuevo** or **otra vez** — *again*.';
update public.tips set title_en = 'Que…: a wish', body_md = 'A wish is *que* + the subjunctive: **que te vaya bien** — *good luck, hope it goes well*, also a friendly goodbye; **que la pases lindo** — *have a great time*; **que tengas buen finde**. The answer to any wish is **gracias, igualmente** — *thanks, you too*. And afterwards you ask **¿cómo te fue?** — *how did it go?* **Pasarla** bien or mal is *to have a good or bad time*: **la pasé re mal**.' where id = '5477ef64-8dc9-564c-912e-6162a954a14d' and body_md = 'A wish is *que* + the subjunctive: **que te vaya bien** — *good luck, hope it goes well*, also a friendly goodbye; **que la pases lindo** — *have a great time*; **que tengas buen finde**. **Pasarla** bien or mal is *to have a good or bad time*: **la pasé re mal**.';
update public.tips set title_en = 'Lo de…', body_md = '**Lo de** is *the thing with*: **¿qué pasó con lo de Juan?** After **a** or **en** it is *someone''s place*: **voy a lo de Sofi**, **estamos en lo de mis viejos**. And **lo de siempre** is *the usual*: at the café, at the bar, in life.' where id = 'c6fee335-6750-566b-8494-37dd8682218f' and body_md = '**Lo de** is *the thing with*: **¿qué pasó con lo de Juan?** And **lo de siempre** is *the usual*: at the café, at the bar, in life.';
update public.tips set title_en = 'Reposo', body_md = 'The doctor''s favorite order: **tenés que hacer reposo** — *you need bed rest*. And a **jarabe** for the cough. A plain **resfrío** — *a cold* — needs no doctor, just a **remedio** from the pharmacy. Anything serious, straight to the **guardia**.' where id = 'c2f0319f-90fd-58b6-9103-689c477c4991' and body_md = 'The doctor''s favorite order: **tenés que hacer reposo** — *you need bed rest*. And a **jarabe** for the cough.';
update public.tips set title_en = 'Igual, a pesar de', body_md = 'Porteños close the thought with **igual** — *anyway*: *aunque esté cansada, voy igual*; *gracias igual* — *thanks anyway*. **De todos modos** says the same but sounds written: *salí de todos modos*. **A pesar de** takes a noun or an infinitive: *a pesar del frío*.' where id = '867bb841-c3ee-5915-a39a-2a142147407f' and body_md = 'Porteños close the thought with **igual** — *anyway*: *aunque esté cansada, voy igual*. **De todos modos** says the same: *salí de todos modos*. **A pesar de** takes a noun or an infinitive: *a pesar del frío*.';
update public.tips set title_en = '-ar takes e, the rest take a', body_md = '**Ayudar → ayudes**, **esperar → esperes**, **mandar → mandes**, **avisar → avises**. *Poner* and *traer* keep the *g* of their *yo*: **pongo → pongas**, **traigo → traiga**. The same form, with **no** in front, tells someone not to: *esperame* — **no me esperes**; *llamame* — **no me llames**. The pronoun jumps to the front.' where id = '28a65e19-7a4f-501c-bed5-b872f18ca04c' and body_md = '**Ayudar → ayudes**, **esperar → esperes**, **mandar → mandes**, **avisar → avises**. *Poner* and *traer* keep the *g* of their *yo*: **pongo → pongas**, **traigo → traiga**.';
update public.tips set title_en = '¿De qué te reís?', body_md = '**Reírse** with *vos*: **¿de qué te reís?**; with *him*: **se ríe de todo**; in the past, **se rió** — *he laughed*. **¿Lloraste?** For the big laugh: **me morí de risa** — *I died laughing*. A **comedia** gets a **sonrisa**; a sad scene, **lágrimas** and **tristeza**. And people with **sentido del humor** laugh at themselves.' where id = '8b879baa-1e7b-5ea3-9967-18510251f924' and body_md = '**Reírse** with *vos*: **¿de qué te reís?**; with *him*, in the past: **se rió** — *he laughed*. **¿Lloraste?** For the big laugh: **me morí de risa** — *I died laughing*. A **comedia** gets a **sonrisa**; a sad scene, **lágrimas** and **tristeza**. And people with **sentido del humor** laugh at themselves.';
update public.tips set title_en = '¿Vos qué opinás?', body_md = '**Opinar** is having a view: **¿vos qué opinás?** — *what do you think?*; **opino lo mismo**. But **yo opino que…** sounds formal, like a TV panel: in daily speech porteños start with **para mí** or **me parece que**: **para mí, depende del tema**; **me parece que tenés razón**.' where id = '02a86818-3208-5fb0-9215-3197ea632302' and body_md = '**Opinar** is having a view: **¿vos qué opinás?** — *what do you think?*. **Yo opino que…** sounds a bit formal: in daily speech, **para mí** starts half the sentences at a porteño table: **para mí, depende del tema**.';
update public.tips set title_en = '-ito, -ita', body_md = '**-ito** makes things small, and requests smaller: **un ratito** — *a little while*; **un cafecito**; **un poquito**. It sounds kind rather than childish. It softens bad news and favors too: **tengo un problemita**, **una preguntita**.' where id = '492ceddb-7a1b-5bbd-9bdf-da57d4115735' and body_md = '**-ito** makes things small, and requests smaller: **un ratito** — *a little while*; **un cafecito**; **un poquito**. It sounds kind rather than childish.';
update public.tips set title_en = 'Cerquita, despacito', body_md = 'It works on adverbs too: **cerquita** — *close by*; **despacito** — *nice and slow*. **Chiquito** — *small, little*. Careful: **hablá más despacito** usually means *keep your voice down*, not *slow down*.' where id = '9c22a7d9-d890-5e17-a088-75954c74be37' and body_md = 'It works on adverbs too: **cerquita** — *close by*; **despacito** — *nice and slow*. **Chiquito** — *small, little*.';
update public.tips set title_en = 'Votar', body_md = 'In Argentina voting is **obligatorio** from 18 to 70 (optional at 16–17 and after 70). **¿A quién votaste?** is a real question, though many answer **eso no se pregunta**. **Votar a** someone: *voté a la misma candidata*. **Votar por** works too: *¿por quién votás?* **Votar en blanco** is to cast a blank vote. And from the night before there is **veda**: no campaigning, and shops and bars can''t sell alcohol.' where id = '67c1e923-9983-5e50-a6ce-52ff85a6eb09' and body_md = 'In Argentina voting is **obligatorio** from 18 to 70 (optional at 16–17 and after 70). **¿A quién votaste?** is a real question, though many answer **eso no se pregunta**. **Votar a** someone: *voté a la misma candidata*. **Votar por** works too: *¿por quién votás?*';
update public.tips set title_en = 'Palta, frutilla', body_md = 'Argentina has its own names: **palta** is avocado, **frutilla** is strawberry. Before you buy, ask **¿están maduras?** — *are they ripe?* The opposite of *madura* is **verde**: **están verdes** — *they are not ripe yet*. (*Es verde* is the color.)' where id = 'fbd2133a-6859-5ead-9926-d782de4ed43e' and body_md = 'Argentina has its own names: **palta** is avocado, **frutilla** is strawberry. Before you buy, ask **¿están maduras?** — *are they ripe?*';
update public.tips set title_en = 'El que avisa no traiciona', body_md = '**El que avisa no traiciona** — *don''t say I didn''t warn you*. You say it while you give the warning. Literally: *the one who warns you doesn''t betray you*. Two you''ll hear every week in Buenos Aires: **sobre gustos no hay nada escrito** — *there''s no accounting for taste*; **el que quiere celeste, que le cueste** — *if you want the good stuff, it will cost you*.' where id = 'e6b7166a-1ef7-5de5-90cc-d87a7c023771' and body_md = '**El que avisa no traiciona** — *don''t say I didn''t warn you*. You say it while you give the warning. Literally: *the one who warns you doesn''t betray you*.';
update public.tips set title_en = 'El cumple', body_md = 'Nobody says *cumpleaños* in a hurry: it''s **el cumple**. For plans, **ir a** + a verb: *el sábado vamos a hacer el cumple de Juan* — and **pasado mañana** is *the day after tomorrow*. The verb is **cumplir**: *¿Cuántos años cumplís?* — *Cumplo treinta.*' where id = '9bbe1671-a5b2-58f1-8923-ddd7c5e66973' and body_md = 'Nobody says *cumpleaños* in a hurry: it''s **el cumple**. For plans, **ir a** + a verb: *el sábado vamos a hacer el cumple de Juan* — and **pasado mañana** is *the day after tomorrow*.';
update public.tips set title_en = 'Me quejo, reniego', body_md = '**Me quejo** — *I complain*; **renegar** is the Argentine *to struggle with something, to grumble*. For a habit: **siempre reniego con el wifi**. For something going on now: **estoy renegando con el trámite del DNI**. Someone who''s **agotado** is *exhausted*; the **estrés** is why. And the traffic? **Un caos**.' where id = '6f45a3bc-6d31-5a43-8fae-bde8329e1e96' and body_md = '**Me quejo** — *I complain*; **reniego** is the Argentine *I struggle with it, I grumble*: **reniego todos los días con el banco**. Someone who''s **agotado** is *exhausted*; the **estrés** is why. And the traffic? **Un caos**.';
update public.tips set title_en = '¿Te arrepentís?', body_md = 'With *vos*: **¿te arrepentís?**; with *him*: **se arrepintió**. **Dejé pasar la oportunidad** — *I let the chance go*. **Te lo perdiste** — *you missed out*. **Metí la pata** — *I made a mistake, I said or did the wrong thing* — or, more porteño, **me mandé una macana**. **¡Qué macana!** — *what a shame*. **Lamentablemente**, you can''t **volver atrás** — so you drop it with **ya fue**.' where id = '54279426-a9ab-597a-90c9-2ebc30ce6253' and body_md = 'With *vos*: **¿te arrepentís?**; with *him*: **se arrepintió**. **Dejé pasar la oportunidad** — *I let the chance go*. **Te lo perdiste** — *you missed out*. **Metí la pata** — *I made a mistake, I said or did the wrong thing*. **Lamentablemente**, you can''t **volver atrás**.';
update public.tips set title_en = 'Descargá, borrá', body_md = 'Tech orders are plain vos commands: **descargá la app**, **borrá las fotos**. What you already did is preterite: **la descargué**, **las borré**. Day to day people say **bajá** or **bajate** for *download*: **bajate la app, es gratis**. *Descargá* is what the screen says.' where id = '6d7c070b-81b7-58f0-b526-20ee5f75be8d' and body_md = 'Tech orders are plain vos commands: **descargá la app**, **borrá las fotos**. What you already did is preterite: **la descargué**, **las borré**. In everyday speech you''ll also hear **bajar** for *download*: **bajate la app**.';
update public.tips set title_en = 'Saying no without quedar mal', body_md = 'Nobody wants to **quedar mal** — *look rude*. So you thank them for the **invitación**, blame a **compromiso** — *a prior commitment* — and leave the door open: **la próxima voy**, **otro día**. And if they push: **no insistas, che**. **Rechazar** needs something after it — *rechacé dos invitaciones* — and sounds formal; day to day people say **decir que no**: *me cuesta decir que no*.' where id = 'cc5e231d-b0ac-5861-be50-d1802854aad9' and body_md = 'Nobody wants to **quedar mal** — *look rude*. So you thank them for the **invitación**, blame a **compromiso** — *a prior commitment* — and leave the door open: **la próxima voy**, **otro día**. And if they push: **no insistas, che**.';
update public.tips set title_en = 'Llegar a fin de mes', body_md = '**Llegar a fin de mes** — *to make it to payday* — is the monthly sport: **no llego a fin de mes**. When the money runs short: **no me alcanza** — *it''s not enough*. You cut the **gastos**, compare **marcas** at the **chino** (the corner supermarket), and notice when they **remarcaron** everything overnight.' where id = 'b1cb665e-4cc4-5bbe-8c24-c91aed8f3fbd' and body_md = '**Llegar a fin de mes** — *to make it to payday* — is the monthly sport. When the money runs short: **no me alcanza** — *it''s not enough*. You cut the **gastos**, compare **marcas** at the **chino** (the corner supermarket), and notice when they **remarcaron** everything overnight.';
update public.tips set title_en = 'Me la jugué, la pifié, la rompe', body_md = 'More verbs that take a **la** pointing at nothing: **me la juego** — *I''ll go for it*; **la pifié** — *I blew it* — and its opposite, **la pegaste** — *you got it right*; **la rompe** — *she''s amazing at it*; **se la agarró conmigo** — *he took it out on me* (he got angry at me, though it wasn''t my fault). **Me las tomo** — *I''m out of here*. And to make someone stop: **¡cortala!** — *cut it out!*' where id = '22bb24f8-8694-59d9-9551-1eae8071c382' and body_md = 'More verbs that take a **la** pointing at nothing: **me la juego** — *I''ll go for it*; **la pifié** — *I blew it*; **la rompe** — *she''s amazing at it*; **se la agarró conmigo** — *he took it out on me* (he got angry at me, though it wasn''t my fault). **Me las tomo** — *I''m out of here*.';
update public.tips set title_en = 'Se tapó, se trabó', body_md = 'Things at home break on their own, with **se**: **se tapó el inodoro** — *the toilet''s clogged*; **se trabó la puerta** — *the door got stuck* (an elevator stuck between floors **se quedó**: *se quedó el ascensor*); **se cortó el agua**. Nobody did it — it just **se rompió**. **La pileta** is the swimming pool and also the kitchen sink — **la pileta de la cocina**, or **la bacha**.' where id = '5c59e9dc-914b-5172-9d87-3fa83a52e4b9' and body_md = 'Things at home break on their own, with **se**: **se tapó el inodoro** — *the toilet''s clogged*; **se trabó la puerta** — *the door got stuck*; **se cortó el agua**. Nobody did it — it just **se rompió**.';
update public.tips set title_en = '¿A quién llamo?', body_md = 'Each problem has its person: the **plomero** for a **canilla** that **gotea** — *a dripping faucet* — the **gasista** for the calefón, the **encargado** for the **portero eléctrico**. A **filtración** from the apartment upstairs goes to the **administración** — *the management office* — and takes months. A toilet or a faucet that leaks **pierde agua**: **el inodoro pierde agua**.' where id = 'e7c5b8b2-bd38-57ba-bd75-9d14c7757dc8' and body_md = 'Each problem has its person: the **plomero** for a **canilla** that **gotea** — *a dripping faucet* — the **gasista** for the calefón, the **encargado** for the **portero eléctrico**. A **filtración** from the apartment upstairs goes to the **administración** — *the management office* — and takes months.';
update public.tips set title_en = 'Brindemos', body_md = 'A porteño **despedida** — *farewell party* — ends with a toast, a **brindis**: **¡brindemos!**, **brindo por ustedes**, **¡salud!** Then **gracias por todo**, **fue un placer**, **los voy a extrañar** — and never *adiós*: you say **chau** or **hasta la próxima**, because here nobody really leaves. To leave, people say **bueno, me voy yendo** or **los dejo**; **me despido** sounds like a letter, though *me despedí de todos* — *I said goodbye to everyone* — is fine.' where id = 'cf2878f8-b900-509f-b7ce-8ab38a91c757' and body_md = 'A porteño **despedida** — *farewell party* — ends with a toast: **¡brindemos!**, **brindo por ustedes**. Then **gracias por todo**, **fue un placer**, and never *adiós*: you say **chau** or **hasta la próxima**, because here nobody really leaves. **Me despido de todos** — *I''m saying goodbye to everyone*.';
update public.tips set title_en = 'Salir con', body_md = '**Estoy saliendo con alguien** — *I''m seeing someone*. When it ends, porteños **cortan**: **cortamos** — *we broke up*. They say **con Juan cortamos** — literally *with Juan we broke up* — for *Juan and I broke up*. A fight is **nos peleamos** — *we had a fight* — or, for them, **se pelearon**; same pattern: **con Sofi nos peleamos** — *Sofi and I had a fight*. **Nos peleamos** is the same for now and for the past: *we fight* / *we had a fight*.' where id = 'dbb9fb4d-69cd-5b88-9d73-7d35bd390442' and body_md = '**Estoy saliendo con alguien** — *I''m seeing someone*. When it ends, porteños **cortan**: **cortamos** — *we broke up*. A fight is **nos peleamos** — *we had a fight* — or, for them, **se pelearon**. **Nos peleamos** is the same for now and for the past: *we fight* / *we had a fight*.';
update public.tips set title_en = 'Any verb can wonder', body_md = '**¿Qué hará?** — *I wonder what he''s doing*; **¿cuánto saldrá?** — *I wonder how much it is* (a textbook says *¿cuánto costará?*; porteños ask prices with *salir*); **vendrá más tarde** — *she''ll probably come later*. For a group: **estarán en el bar**, **serán las ocho**. To vos, the question is **¿estarás cansado?**; the statement is **debés estar cansado** — *you must be tired*. And for a plain future porteños skip this tense: **no sé si va a venir**, **seguro que no viene**.' where id = 'ce15b13a-f188-5034-9617-6e20515212c2' and body_md = '**¿Qué hará?** — *I wonder what he''s doing*; **¿cuánto costará?** — *I wonder how much it is*; **vendrá más tarde** — *she''ll probably come later*. For a group: **estarán en el bar**, **serán las ocho**. To vos: **¿estarás cansado?** — *you must be tired*.';
update public.tips set title_en = 'Me salvaste', body_md = 'Porteño thanks praise the person: **sos un genio**, **me salvaste** — *you saved me*. To a woman it is always **sos una genia**. For a present: **¡qué detalle!** — *how thoughtful!* — or **¡te pasaste!** — *this is too much, you did an amazing job!* Said in an angry voice, the same words mean *you went too far*.' where id = '88b903ef-e0f8-5900-86f6-a2d183e36dce' and body_md = 'Porteño thanks praise the person: **sos un genio**, **me salvaste** — *you saved me*. For a present: **¡qué detalle!** — *how thoughtful!* — or **¡te pasaste!** — *this is too much, you did an amazing job!* Said in an angry voice, the same words mean *you went too far*.';
update public.tips set title_en = 'Micro, not colectivo', body_md = 'The *colectivo* crosses the city; to go to another city you take the **micro** (the long-distance bus). You buy the **pasaje** at the terminal or online. A round-trip ticket is **ida y vuelta**. In Buenos Aires the micros leave from the **terminal** of Retiro, and the airports are Ezeiza (international) and Aeroparque (in the city).' where id = 'e6e2d7cb-a37e-547a-b841-bd24476880df' and body_md = 'The *colectivo* crosses the city; to go to another city you take the **micro** (the long-distance bus). You buy the **pasaje** at the terminal or online.';
update public.tips set title_en = 'Subir, bajar, cobrar', body_md = 'Prices **suben** — or **aumentan**, same thing — and, now and then, **bajan**. **¿Cuánto te cobraron?** — *how much did they charge you?* **Cobrar** is also *to get paid*: **cobro el viernes** — *I get paid on Friday*; **¿ya cobraste?** A **precio** is a price; *está a buen precio* — *it''s a good price*. When it isn''t: **es un afano** — *it''s a rip-off*; **está por las nubes** — *sky-high*; **sale un ojo de la cara** — *it costs a fortune*.' where id = '8af67e04-9d96-5ada-98ea-78bbea30080c' and body_md = 'Prices **suben** — or **aumentan**, same thing — and, now and then, **bajan**. **¿Cuánto te cobraron?** — *how much did they charge you?* A **precio** is a price; *está a buen precio* — *it''s a good price*.';
update public.tips set title_en = '¿Qué te parece?', body_md = '**¿Qué te parece?** — *what do you think?* — and the answer **me parece bien** — *sounds good* — or **me parece que no** — *I don''t think so*. **No me parece que** takes the subjunctive, like *no creo que*: *no me parece que sea caro*. Day to day an opinion starts with **para mí**: **para mí, es caro**; **para mí que no viene** — *I think he''s not coming*. And to dodge the question: **ni idea**.' where id = '3720e015-a831-5b88-af8b-2c4948855038' and body_md = '**¿Qué te parece?** — *what do you think?* — and the answer **me parece bien** — *sounds good* — or **me parece que no** — *I don''t think so*. **No me parece que** takes the subjunctive, like *no creo que*: *no me parece que sea caro*.';
update public.tips set title_en = 'No anda', body_md = 'For machines, porteños say **anda** — *it works*: **no anda el wifi**, **¿anda el ascensor?**. *Funciona* means the same and is just as common. The other ways things fail: **se rompió**, **está roto**, **no prende** — *it won''t turn on*; **se colgó** — *it froze*; **pierde agua** — *it''s leaking*.' where id = '17c1c9e2-7e28-5f37-a171-3f6f56f5e112' and body_md = 'For machines, porteños say **anda** — *it works*: **no anda el wifi**, **¿anda el ascensor?**. *Funciona* means the same and is just as common.';
update public.tips set title_en = 'Para mí', body_md = '**Para mí**, **me parece que**, **coincido**, **al contrario** — the whole argument. *Opino que* is for TV panels: at the table it is **para mí, el árbitro estuvo mal**. And the line that ends it: **¡no exageres!** For advice, **tendrías que** — *you should*: **tendrías que ir al médico**.' where id = 'd74aeb37-59af-5591-be40-ad3811e93ce1' and body_md = '**Para mí**, **opino que**, **coincido**, **al contrario** — the whole argument. And the line that ends it: **¡no exageres!** For advice, **tendrías que** — *you should*: **tendrías que ir al médico**.';
update public.tips set title_en = 'Fillers', body_md = 'A porteño sentence breathes through its fillers: **ponele** — *let''s say*; **digamos** — *sort of*; **qué sé yo** — *I don''t know*; **bah** — *well, I mean*: *son las ocho, bah, ponele*. The ones you will hear most: **o sea** — *I mean*; **tipo** — *like, around*: *es tipo a las nueve*; and **viste** at the end, for *you know*: *estaba cansado, viste*.' where id = '6adce778-5bd3-5ead-8fc5-69d118ef84f7' and body_md = 'A porteño sentence breathes through its fillers: **ponele** — *let''s say*; **digamos** — *sort of*; **qué sé yo** — *I don''t know*; **bah** — *well, I mean*: *son las ocho, bah, ponele*.';
update public.tips set title_en = 'Yes, no, and no way', body_md = '**¡Más vale!** — *of course!*; **sí o sí** — *no matter what*; **ni loco** — *no way* — and a woman says **ni loca**: *¿volver con mi ex? Ni loca.* Before a verb **más vale** is *you''d better*: **más vale llevar paraguas**, **más vale que llegues temprano** (subjunctive after *que*). And when there''s too much going on: **estoy a full** — *I''m really busy*.' where id = 'c6b40c9b-6758-5732-b6d5-1a559be96347' and body_md = '**¡Más vale!** — *of course!*; **sí o sí** — *no matter what*; **ni loco** — *no way*. Before a verb it''s *you''d better*: **más vale llevar paraguas**, **más vale que llegues temprano** (subjunctive after *que*). And when there''s too much going on: **estoy a full** — *I''m really busy*.';
update public.tips set title_en = 'Creció', body_md = '**Crecer** is *to grow* — a city, a kid, a tree: **el barrio creció**, **crecí en Rosario** — *I grew up in Rosario*. Porteños also say **me crié**: *me crié en Flores* — *I grew up in Flores*. A building is an **edificio**: **hay cada vez más edificios**.' where id = '3b867a4a-8a39-52fc-bdb4-73a4c0c46453' and body_md = '**Crecer** is *to grow* — a city, a kid, a tree: **el barrio creció**, **crecí en Rosario** — *I grew up in Rosario*. A building is an **edificio**: **hay cada vez más edificios**.';
update public.tips set title_en = 'Talle', body_md = 'Your clothing size is your **talle**: *¿Qué talle usás?* (you''ll also hear *¿Qué talle sos?*) Argentine sizes run small, so ask to try it on before you pay: **¿Puedo probarme esto?**' where id = '834d42dc-2aa8-5ffa-b50d-ecbf01e319e5' and body_md = 'Your clothing size is your **talle**: *¿Qué talle usás?* (you''ll also hear *¿Qué talle sos?*) Argentine sizes run small, so ask to try it on before you pay.';
update public.tips set title_en = 'Pasaría, devolvería', body_md = 'What he swore he''d do, told later — the everyday way: **dijo que iba a pasar**, **me aseguró que me lo iba a devolver**. More careful, and in writing: **dijo que pasaría**, **me lo devolvería**. Two have a changed stem: *poner* → **pondría**, *venir* → **vendría**.' where id = 'bf2dc98a-75d6-56a8-a981-915fd847826c' and body_md = 'What he swore he''d do, told later: **dijo que pasaría**, **me aseguró que me lo devolvería**. Two have a changed stem: *poner* → **pondría**, *venir* → **vendría**.';
update public.tips set title_en = 'Lo lograste', body_md = '**Lograr** — *to manage, to pull off*: **¡lo lograste!** — *you did it!* And your own line: **¡lo logré!** — *I did it!* Then **felicitaciones** — *congratulations* — or, among friends, just **¡grande!**' where id = 'bb475835-3596-5744-abe5-6a802edce685' and body_md = '**Lograr** — *to manage, to pull off*: **¡lo lograste!** — *you did it!* Then **felicitaciones** — *congratulations* — or, among friends, just **¡grande!**';
update public.tips set title_en = 'Only after si', body_md = 'You meet the **-ra** form (*tuviera*, *pudiera*) after *si* (if) and after *ojalá* (I wish), and almost nowhere else at this level. Mind the difference: **ojalá llueva** — *I hope it rains* (it can happen); **ojalá pudiera ir** — *I wish I could go* (it is not real).' where id = '04f23526-26bf-5316-8fb2-a5c912c8462f' and body_md = 'You meet the **-ra** form (*tuviera*, *pudiera*) after *si* (if) and after *ojalá* (I wish) — **ojalá pudiera**, *I wish I could* — and almost nowhere else at this level.';
update public.tips set title_en = 'Arreglar', body_md = '**¿Me lo podés arreglar?** — *can you fix it for me?* After the **técnico** comes: **lo arregló en cinco minutos** — *he fixed it in five minutes*. If he never comes, **hacés un reclamo** — *you file a complaint* — and **nos quejamos** all summer. The questions for the técnico: **¿tiene arreglo?** — *can it be fixed?*; **¿cuánto me sale el arreglo?**; **¿cuándo podés venir?**' where id = 'c3650361-726d-523a-93eb-fc3114f524cd' and body_md = '**¿Me lo podés arreglar?** — *can you fix it for me?* After the **técnico** comes: **lo arregló en cinco minutos** — *he fixed it in five minutes*. If he never comes, **hacés un reclamo** — *you file a complaint* — and **nos quejamos** all summer.';
update public.tips set title_en = 'Según', body_md = '**Según** — *according to*: **según el diario**, **según mi vieja**. **Al parecer** and **supuestamente** keep a distance from what you''re passing on. **Al parecer** sounds like the news; in chat people say **por lo visto** or **parece que**: *por lo visto, Sofi tiene novio nuevo*; *parece que no viene*.' where id = '5c404af7-97bb-5016-95f3-4dbb7f00df17' and body_md = '**Según** — *according to*: **según el diario**, **según mi vieja**. **Al parecer** and **supuestamente** keep a distance from what you''re passing on. **Al parecer** sounds like the news; in chat people say **por lo visto** or **parece que**.';
update public.tips set title_en = 'Te aconsejo que, conviene que', body_md = '| Te aconsejo que **lleves** efectivo. | My advice: bring cash. |
| Conviene que **tomes** el subte. | Best to take the subway. |
| Es mejor que **reserves**. | Better book ahead. |
| Es importante que **uses** la SUBE. | Use your SUBE card. |
| Es mejor que **salgamos** temprano. | We''d better leave early. |

Advice with **que** takes the subjunctive. In everyday speech the short way wins — no *que*, just the infinitive: *te conviene reservar hoy*, *te conviene tomar el subte*, *te recomiendo ir en subte*. *-ar* verbs take **e** (*llevar* → **lleves**), the rest **a** (*salgo* → **salgamos**).' where id = 'ccbc17ab-2f02-5887-84a7-3b706a5db8ec' and body_md = '| Te aconsejo que **lleves** efectivo. | My advice: bring cash. |
| Conviene que **tomes** el subte. | Best to take the subway. |
| Es mejor que **reserves**. | Better book ahead. |
| Es importante que **uses** la SUBE. | Use your SUBE card. |
| Es mejor que **salgamos** temprano. | We''d better leave early. |

Advice with **que** takes the subjunctive. Without *que*, use the infinitive: *te conviene reservar*, *te recomiendo ir en subte*. *-ar* verbs take **e** (*llevar* → **lleves**), the rest **a** (*salgo* → **salgamos**).';
update public.tips set title_en = 'Me olvidé de…', body_md = '**Me olvidé de su cumple** — *I forgot his birthday*. Like *me enojé* it keeps its pronoun, and takes **de** before what you forgot. Left something behind? No *de*: **me olvidé las llaves en casa**. For the others: **¿te olvidaste las llaves?**, **se olvidó de llamar**, **nos olvidamos de reservar**. Same shape: **me aburrí**, **me calmé**, **me enamoré** — of Buenos Aires, of course.' where id = '964d8d97-0008-5be6-9c6c-5b9aeb6147f7' and body_md = '**Me olvidé de su cumple** — *I forgot his birthday*. Like *me enojé* it keeps its pronoun, and takes **de** before what you forgot. Left something behind? No *de*: **me olvidé las llaves en casa**. Same shape: **me aburrí**, **me calmé**, **me enamoré** — of Buenos Aires, of course.';
update public.tips set title_en = '¿Cuánto demora?', body_md = 'For paperwork, **demorar** is how long something takes: **¿cuánto demora la residencia?** The honest answer is *depende*. For a person or a bus porteños say **tardar**: *Lucía tardó media hora*, *el bondi tardó un montón*. You **presentás** the papers, and when they finally **atienden** you, it''s over in five minutes.' where id = '0a7f761b-d9c7-516c-b579-5874def00152' and body_md = 'For paperwork, **demorar** is how long something takes: **¿cuánto demora la residencia?** In everyday talk porteños mostly say **tardar**: *el colectivo tarda*. The honest answer is *depende*. You **presentás** the papers, and when they finally **atienden** you, it''s over in five minutes.';
update public.tips set title_en = 'Me afanaron, nos robaron', body_md = 'Among friends it''s **me afanaron** — *they stole it* (slang) — with the same *they* that nobody names. It moves with the victim: **te robaron**, **le robaron a mi vieja**, **nos robaron la bici**. The **motochorro** does it from a motorbike. It is also what you say when you were overcharged: **me afanaron con el taxi** — *the taxi ripped me off*.' where id = '9f1b4f75-62bb-5fd3-bfb4-117dc43f4612' and body_md = 'Among friends it''s **me afanaron** — *they stole it* (slang) — with the same *they* that nobody names. It moves with the victim: **te robaron**, **le robaron a mi vieja**, **nos robaron la bici**. The **motochorro** does it from a motorbike.';
update public.tips set title_en = 'The ones grandma says', body_md = '**Más vale pájaro en mano que cien volando** — *one sure thing is better than a hundred possible ones*; **a caballo regalado no se le miran los dientes** — *you don''t complain about a gift*; **ojos que no ven, corazón que no siente** — *what you don''t know can''t hurt you*; **del dicho al hecho hay mucho trecho** — *easier said than done*. **El que se quema con leche, ve una vaca y llora** — *after a bad experience, you''re scared of anything similar*. For someone who complicates everything: **buscarle la quinta pata al gato** — *to look for the cat''s fifth leg*. And when someone walks in: **hablando del rey de Roma…** — *we were just talking about you*' where id = 'c856ee20-16fd-55e2-88a7-bb617e0c577d' and body_md = '**Más vale pájaro en mano que cien volando** — *one sure thing is better than a hundred possible ones*; **a caballo regalado no se le miran los dientes** — *you don''t complain about a gift*; **ojos que no ven, corazón que no siente** — *what you don''t know can''t hurt you*; **del dicho al hecho hay mucho trecho** — *easier said than done*. **El que se quema con leche, ve una vaca y llora** — *after a bad experience, you''re scared of anything similar*. And when someone walks in: **hablando del rey de Roma…** — *we were just talking about you*';
update public.tips set title_en = 'Don, doña', body_md = 'The old neighbor is **don José** or **doña Rosa** — first name, with respect. A **persona mayor**, a **jubilado**, still gets **vos**, plus a **cómo no** (*of course*) and a **permiso** when you need to get past — *con permiso* exists, but porteños mostly say just **permiso**, and you **pedís permiso** before going in: *entró sin pedir permiso*.' where id = '0da84ce9-08d5-56d5-bf04-81b8a54b1746' and body_md = 'The old neighbor is **don José** or **doña Rosa** — first name, with respect. A **persona mayor**, a **jubilado**, still gets **vos**, plus a **cómo no** (*of course*) and a **con permiso** when you need to get past.';
update public.tips set title_en = 'The move itself', body_md = 'You rent through an **inmobiliaria** or straight from the **dueño**, and pay the **alquiler** every month. On top of the rent come the **expensas** — *the building fees* — and to move in you leave a **depósito**. A **flete** takes the **muebles** and the **colchón**, and before unpacking, **pintamos**. And *they moved* is **se mudaron**. The dream is the **casa propia** — *a place of your own*.' where id = 'dbad321f-4d32-5c2e-9458-5dbbd5e6decf' and body_md = 'You rent through an **inmobiliaria** or straight from the **dueño**, and pay the **alquiler** every month. A **flete** takes the **muebles** and the **colchón**, and before unpacking, **pintamos**. And *they moved* is **se mudaron**.';
update public.tips set title_en = 'Out of the city', body_md = 'Leaving Buenos Aires you take **la autopista** (the fast road, with tolls), then **la ruta** (the ordinary road between towns). First you **cargás nafta** — *nafta*, never *gasolina* — and on the way you pay the **peaje**. **La General Paz** is the ring road between the Capital and the conurbano. Porteños *agarran* a road rather than *take* it: **agarrá la ruta**, **¿qué ruta agarramos?**' where id = '97e6c524-59bf-5483-b652-95a1e627cae7' and body_md = 'Leaving Buenos Aires you take **la autopista** (the fast road, with tolls), then **la ruta** (the ordinary road between towns). First you **cargás nafta** — *nafta*, never *gasolina* — and on the way you pay the **peaje**. **La General Paz** is the ring road between the Capital and the conurbano.';
update public.tips set title_en = 'Ser socio', body_md = 'To go to **la cancha** — *estadio* is for signs and maps — you are usually **socio** — *a member* — of the **club**, and pay the cuota. Tickets are *entradas*: the **popular** is the cheap standing end, the **platea** the seats. The **hinchada** sings its **cantitos** for ninety minutes, under the **banderas**. Away fans? Mostly banned since 2013: you usually only go **de visitante** on TV.' where id = 'bcc20295-b0f0-5657-8bba-544e8abc8f78' and body_md = 'To go to the **estadio** you''re **socio** — *a member* — of the **club**, and pay the cuota. The **hinchada** sings its **cantitos** for ninety minutes, under the **banderas**. Away fans? Mostly banned since 2013: you usually only go **de visitante** on TV.';
update public.tips set title_en = 'Harto, podrido', body_md = '**Estoy harto** — *I''m fed up*; porteños go further: **estoy podrido** — literally *rotten*. Both take **de** + a thing or an infinitive: **harta del tránsito**, **podrido del ruido**, **harta de estudiar**. Same with **me cansé de esperar** — *I got tired of waiting*. When someone or something else is doing it: **de que** + subjunctive — *estoy podrido de que el ascensor esté roto*.' where id = 'aba5baad-8a36-5ee9-8293-ce942fa3dc14' and body_md = '**Estoy harto** — *I''m fed up*; porteños go further: **estoy podrido** — literally *rotten*. Both take **de** + a thing or an infinitive: **harta del tránsito**, **podrido del ruido**, **harta de estudiar**. Same with **me cansé de esperar** — *I got tired of waiting*.';
